static class Test {
 sealed record Active(string ItemId,string Path);
 sealed class Editing {readonly SemaphoreSlim gate=new(1,1);readonly Dictionary<string,Active> sessions=new();public Editing(string id,string path){sessions.Add("real-session",new(id,path));}public void Move(string path){var old=sessions["real-session"];sessions["real-session"]=old with{Path=path};}}
