 static int checks;static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
 static void Refuse(Action action,string label){try{action();}catch(Exception e)when(e is IOException or InvalidDataException){Check(true,label);return;}throw new Exception("Expected refusal: "+label);}
 static byte[] Pack(string id,string title){using var stream=new MemoryStream();using(var z=new ZipArchive(stream,ZipArchiveMode.Create,true)){void Add(string name,string value){using var writer=new StreamWriter(z.CreateEntry(name).Open(),new UTF8Encoding(false));writer.Write(value);}Add("text.md","---\ntextTextId: "+id+"\n---\nbody");Add("document.json",JsonSerializer.Serialize(new{schemaVersion=1,content=new{title,body="body"}}));Add("assets/test.bin","actual asset bytes");}return stream.ToArray();}
 static async Task Main(){AssetProofProfile6Tests.Run(Check);await AssetProofObservationTests.Run(Check);foreach(var n in new[]{0,1,120}){var sample=JsonSerializer.SerializeToElement(new{version=1,id="owned:soak:"+n});Check(SoakSample.Validate(sample,"owned").GetProperty("id").GetString()=="owned:soak:"+n,"current soak sample "+n);}foreach(var sampleId in new[]{"owned:soak:01","owned:soak:121","other:soak:0"})Refuse(()=>SoakSample.Validate(JsonSerializer.SerializeToElement(new{version=1,id=sampleId}),"owned"),"foreign/noncanonical soak refused "+sampleId);Refuse(()=>SoakSample.Validate(JsonSerializer.SerializeToElement(new{version=2,id="owned:soak:0"}),"owned"),"future soak refused");Refuse(()=>SoakSample.Validate(JsonSerializer.SerializeToElement(new{version=true,id="owned:soak:0"}),"owned"),"boolean soak version refused");Refuse(()=>SoakSample.Validate(JsonSerializer.SerializeToElement(new{version=1,id="owned:soak:0",future=true}),"owned"),"future soak field refused");var temporary=Path.GetTempPath();if(OperatingSystem.IsMacOS()&&temporary.StartsWith("/var/"))temporary="/private"+temporary;var root=Path.Combine(temporary,"texttext-leaf-move-fixture-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var parent="Six-client acceptance folder "+Guid.NewGuid();Directory.CreateDirectory(Path.Combine(root,parent));var title="Six-client acceptance original";var source=parent+"/"+title+".textpack";var destination=parent+"/Six-client acceptance moved.textpack";var id=Guid.NewGuid().ToString();var a=Path.Combine(root,source);var b=Path.Combine(root,destination);File.WriteAllBytes(a,Pack(id,title));var scenario=JsonSerializer.SerializeToElement(new{role="pc-cli",round=1,source,destination});JsonElement Request(string phase)=>JsonSerializer.SerializeToElement(new{version=1,operationId="lm-"+new string('a',32),phase,scenario});
 LeafMoveObservation.ValidateConfig(a,title,scenario);Check(true,"original leaf config accepted without title mutation");LeafMoveObservation.ValidateConfig(b,title,scenario);Check(true,"reopen destination config binds immutable original title");Refuse(()=>LeafMoveObservation.ValidateConfig(Path.Combine(root,parent,"unrelated.textpack"),title,scenario),"undeclared title mismatch refused");
 var editing=new Editing(id,source);var bridge=new Bridge(editing);Check(await LeafMoveObservation.SelectedPath(bridge,id,default)==source,"selected path reads actual active session");
 if(!OperatingSystem.IsWindows()) {Refuse(()=>LeafMoveObservation.Observe(root,"workspace",id,title,a,scenario,Request("before"),source),"filesystem proof fails closed without Windows native identity");Check(Encoding.UTF8.GetString(LeafMoveObservation.Canonical(JsonSerializer.SerializeToElement(new{z=1,a="café"})))=="{\"a\":\"café\",\"z\":1}","canonical document keys and UTF8 agree");Console.WriteLine($"{checks} portable actor checks passed; Windows filesystem checks require actual PC");return;}
 var before=LeafMoveObservation.Observe(root,"workspace",id,title,a,scenario,Request("before"),source);var bp=JsonSerializer.SerializeToElement(before.Proof);Check(!before.Pending&&bp.GetProperty("sourcePresent").GetBoolean()&&bp.GetProperty("assetHashes").GetProperty("assets/test.bin").GetString()==TextPackStore.Hash(Encoding.UTF8.GetBytes("actual asset bytes")),"before proof includes exact real asset and source");
 Refuse(()=>LeafMoveObservation.Observe(root,"workspace",id,title,a,scenario,Request("before"),destination),"before proof refuses a different live selected endpoint");
 var future=JsonSerializer.SerializeToElement(new{version=2,operationId="lm-"+new string('a',32),phase="before",scenario});Refuse(()=>LeafMoveObservation.Observe(root,"workspace",id,title,a,scenario,future,source),"future observation version refused");
 File.Move(a,b);Check(await LeafMoveObservation.SelectedPath(bridge,id,default)==source,"disk rename does not fabricate moved selected session path");var pending=LeafMoveObservation.Observe(root,"workspace",id,title,a,scenario,Request("after"),source);Check(pending.Pending,"actual stale selected session remains pending");editing.Move(destination);var after=LeafMoveObservation.Observe(root,"workspace",id,title,b,scenario,Request("after"),await LeafMoveObservation.SelectedPath(bridge,id,default));var ap=JsonSerializer.SerializeToElement(after.Proof);Check(!after.Pending&&ap.GetProperty("relativePath").GetString()==destination&&!ap.GetProperty("sourcePresent").GetBoolean(),"after proof requires actual selected session follow");Check(bp.GetProperty("archiveSha256").GetString()==ap.GetProperty("archiveSha256").GetString()&&bp.GetProperty("documentSha256").GetString()==ap.GetProperty("documentSha256").GetString(),"path-only move preserves exact bytes and canonical document");
 var duplicate=Path.Combine(root,"duplicate.textpack");File.Copy(b,duplicate);Refuse(()=>LeafMoveObservation.Observe(root,"workspace",id,title,b,scenario,Request("after"),destination),"duplicate stable identity elsewhere in workspace refused");File.Move(duplicate,Path.Combine(root,"retained-duplicate.bin"));
 File.WriteAllText(Path.Combine(root,parent,"unknown.bin"),"untouched");Refuse(()=>LeafMoveObservation.Observe(root,"workspace",id,title,b,scenario,Request("after"),destination),"unknown membership refused without mutation");Check(File.ReadAllText(Path.Combine(root,parent,"unknown.bin"))=="untouched","unknown entry preserved");
 var folded=JsonSerializer.SerializeToElement(new{role="pc-cli",round=1,source,destination=source.ToUpperInvariant()});Refuse(()=>LeafMoveObservation.Validate(folded,title),"case-only alias remains outside ordinary leaf scenario");Console.WriteLine($"{checks} private actor leaf proofs passed; retained fixture: {root}");}
}
